    type: 'object',
    required: ['location', 'contact', 'units'],
    properties: {
      location: {type: 'string', format: 'custom-unknown-format'},
      contact: {type: 'object', required: ['email'], properties: {email: {type: 'string', format: 'email'}}},
      units: {type: 'string', enum: ['celsius', 'fahrenheit']},
    },
  });
  const ok = validate({location: 'not-a-format', contact: {email: 'not-an-email'}, units: 'celsius', extra: 1});
  const bad = validate({contact: {email: 987654}, units: 'kelvin'});
  console.log(label, {ok, bad, errors: validate.errors});
}
